// Hand-written Verilog testbench for AC-MVP-015.
//
// It is deliberately not generated by ShyHDL: a failure here must be a DUT
// failure, never a testbench-generation failure. `PacketMake.pkt` is wired
// straight into `PacketSplit.pkt`, so the two modules are checked as a chain.
//
// The 44-bit layout is stated independently here as `{ op, addr, flag, tag }`:
// declaration order, most significant field first, no padding (REQ-LANG-003).
// A round trip alone would still pass with a mirrored layout, so the layout is
// asserted on its own.
//
// Protocol: exactly one `SHYHDL-AC-PASS packet ...` line on success, otherwise
// `SHYHDL-AC-FAIL packet ...` lines. A run with no verdict is a failure.
//
// Expects the frontend-generated modules: PacketMake, PacketSplit.

`timescale 1ns/1ps

module tb_packet;
    localparam integer SWEEP_OPS = 16;
    localparam integer SWEEP_TAGS = 128;
    localparam integer SPECIALS = 6;
    localparam integer EXPECTED_COMBOS = SWEEP_OPS * SWEEP_TAGS + SPECIALS;

    reg  [3:0]  op;
    reg  [31:0] addr;
    reg         flag;
    reg  [6:0]  tag;

    wire [43:0] pkt;
    wire [3:0]  op_out;
    wire [31:0] addr_out;
    wire        flag_out;
    wire [6:0]  tag_out;

    integer    i, k, combos, failures;
    reg [31:0] sweep_addr;

    PacketMake  dut_make  (.op(op), .addr(addr), .flag(flag), .tag(tag), .pkt(pkt));
    PacketSplit dut_split (.pkt(pkt), .op(op_out), .addr(addr_out), .flag(flag_out), .tag(tag_out));

    task check_field;
        input [255:0] what;
        input [63:0]  got;
        input [63:0]  want;
        begin
            if (got !== want) begin
                failures = failures + 1;
                if (failures <= 12)
                    $display("SHYHDL-AC-FAIL packet %0s got=%h want=%h (op=%h addr=%h flag=%b tag=%h)",
                             what, got, want, op, addr, flag, tag);
            end
        end
    endtask

    task drive_and_check;
        input [3:0]  o;
        input [31:0] ad;
        input        f;
        input [6:0]  tg;
        begin
            op = o;
            addr = ad;
            flag = f;
            tag = tg;
            #1;
            combos = combos + 1;
            check_field("layout", pkt, {o, ad, f, tg});
            check_field("roundtrip.op", op_out, o);
            check_field("roundtrip.addr", addr_out, ad);
            check_field("roundtrip.flag", flag_out, f);
            check_field("roundtrip.tag", tag_out, tg);
        end
    endtask

    initial begin
        failures = 0;
        combos = 0;
        op = 4'h0;
        addr = 32'h0000_0000;
        flag = 1'b0;
        tag = 7'h00;

        // Boundary patterns: every field all-zero and all-one, and single set
        // bits at both ends of each field.
        drive_and_check(4'h0, 32'h0000_0000, 1'b0, 7'h00);
        drive_and_check(4'hF, 32'hFFFF_FFFF, 1'b1, 7'h7F);
        drive_and_check(4'hF, 32'h0000_0000, 1'b0, 7'h00);
        drive_and_check(4'h0, 32'h0000_0000, 1'b1, 7'h7F);
        drive_and_check(4'h8, 32'h8000_0000, 1'b0, 7'h40);
        drive_and_check(4'h1, 32'h0000_0001, 1'b1, 7'h01);

        // Field-by-field sweep: every `op` and every `tag`, with addresses that
        // move four different byte lanes so no byte can be silently dropped.
        for (i = 0; i < SWEEP_OPS; i = i + 1) begin
            for (k = 0; k < SWEEP_TAGS; k = k + 1) begin
                sweep_addr = {i[3:0], 8'hA5, k[7:0], 8'h5A, k[3:0]};
                drive_and_check(i[3:0], sweep_addr, k[0], k[6:0]);
            end
        end

        if (failures == 0 && combos == EXPECTED_COMBOS)
            $display("SHYHDL-AC-PASS packet combos=%0d", combos);
        else
            $display("SHYHDL-AC-FAIL packet failures=%0d combos=%0d expected_combos=%0d",
                     failures, combos, EXPECTED_COMBOS);
        $finish;
    end

    initial begin
        #100000;
        $display("SHYHDL-AC-FAIL packet timeout at %0t: no verdict was printed", $time);
        $finish;
    end
endmodule
